":"end","alignItems":"center"}},{"id":"warning_panel","component":"Column","children":["warning_text","remind_text"],"itemMargin":4,"styles":{"width":100,"height":68,"padding":8,"borderRadius":16,"backgroundColor":"#ffffffff","justifyContent":"center","alignItems":"start"}},{"id":"warning_text","component":"Text","content":"{{ ${/ui/warningText} }}","styles":{"width":84,"height":32,"fontSize":14,"fontWeight":700,"fontColor":"#e5000000","maxLines":2}},{"id":"remind_text","component":"Text","content":"{{ ${/data/calendar/items/0/remindTime/0} }}","styles":{"width":84,"height":16,"fontSize":12,"fontWeight":400,"fontColor":"#99000000","maxLines":1}},{"id":"action_button","component":"Button","label":"{{ ${/ui/reviewTargetText} }}","onClick":[{"call":"clickToDeeplink","args":{"bundleName":"com.huawei.hmos.settings","abilityName":"com.huawei.hmos.settings.MainAbility","uri":"parent_control"}}],"styles":{"width":100,"height":36,"fontSize":14,"fontWeight":"medium","fontColor":"#ffffffff","backgroundColor":"#ff0a59f7","borderRadius":18}}]}}
